<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted, watch, nextTick } from 'vue'
import { House, ListMusic, Search, ListChecks, Library, Settings, Plus, ArrowUpRight, ArrowLeft, ArrowUp, ArrowDown, RefreshCw, Check, ChevronRight, ChevronLeft, X, Pause, Play, Disc3, Music2, LockKeyhole, LogOut, Upload, Download, CircleHelp, CircleAlert, HardDrive, Activity, FileMusic, LoaderCircle, SlidersHorizontal, Clock3 } from 'lucide-vue-next'
import { api, setCsrf, bytes, date, duration, taskDate, elapsed } from './api'
import Player from './Player.vue'
import PersonalHub from './PersonalHub.vue'
import SourceManager from './SourceManager.vue'
import ChartSubscriptions from './ChartSubscriptions.vue'
import { version } from '../package.json'
import { refreshPwaCache } from './pwa'
import { player, playSongs, enqueueSongs, stop, savePlayback, setPlayerAccount } from './player'

type Tab = 'home'|'playlists'|'search'|'jobs'|'library'|'settings'
const tabs = [{id:'home',label:'总览',icon:House},{id:'playlists',label:'歌单',icon:ListMusic},{id:'search',label:'找音乐',icon:Search},{id:'jobs',label:'任务',icon:ListChecks},{id:'library',label:'音乐库',icon:Library}]
const titles: Record<Tab,string> = {home:'总览',playlists:'歌单管理',search:'找音乐',jobs:'整理任务',library:'音乐库',settings:'设置'}
const descriptions: Record<Tab,string> = {home:'歌单会变，喜欢的声音可以一直在。',playlists:'留意歌单的变化，把新增的喜欢带回音乐库。',search:'输入歌名和歌手，选对版本，再加入收藏。',jobs:'关闭页面也会继续。每一步都有据可查。',library:'喜欢的音乐放在 NAS，随时点开听一听。',settings:'来源、投递文件和运行状态，都在这里。'}
const username=ref('admin'), user=ref<any>(null), personalMode=ref(true)
async function manage(){personalMode.value=false;await loadTab()}
function identity(s:any){user.value={...s.user,server_id:s.server_id};setPlayerAccount(s.server_id,s.user.id)}
const tab = ref<Tab>('home'), logged = ref(false), ready = ref(false), password = ref(''), busy = ref(''), error = ref(''), toast = ref('')
const overview = ref<any>(null), playlists = ref<any[]>([]), jobs = ref<any>({items:[],total:0}), library = ref<any>({items:[],total:0}), settings = ref<any>(null), system = ref<any>(null)
const query = ref(''), platform = ref('netease'), searchResults = ref<any[]>([]), searched = ref(false), searchPage = ref(1)
const libraryQuery = ref(''), libraryFilter = ref('all'), libraryPage = ref(1), selected = ref<string[]>([]), jobFilter = ref('all'), jobPage = ref(1)
const modal = ref(''), dialog = ref<HTMLDialogElement|null>(null), detail = ref<any>(null), candidate = ref<any>(null), playlistDetail = ref<any>(null), jobDetail = ref<any>(null)
const targetPlaylist = ref(localStorage.getItem('music-target-playlist')||''), libraryFolder = ref(''), playlistVisible = ref(100)
const share = ref(''), preview = ref<any>(null), importMode = ref('watch'), autoAdd = ref(false)
const inbox = ref<any[]>([]), linkedFile = ref<any>(null), linkedAsset = ref<any>(null), linkedOriginal = ref<any>(null), mappingConfirmed = ref(false)
const providerNames = computed<Record<string,string>>(()=>({gd:'GD 音乐台',netease_direct:'网易云公开音频',tencent_direct:'QQ 公开音频',...settings.value?.provider_names}))
const stateNames: Record<string,string> = {queued:'等待中',running:'处理中',succeeded:'已完成',failed:'需要处理',paused:'已暂停',cancelled:'已取消',review:'待确认版本'}
const oldPassword = ref(''), newPassword = ref(''), offline = ref(!navigator.onLine), secure = window.isSecureContext
const taskPolicy = ref<any>(null)
const stale = ref(false), scanIssues = ref<any[]>([])
const showDiff = ref(false), installPrompt = ref<any>(null), cpu = ref<number|null>(null)
let timer: ReturnType<typeof setInterval>, toastTimer: ReturnType<typeof setTimeout>, previousCpu: {seconds:number,time:number}|null = null
const activeCount = computed(()=>overview.value ? (overview.value.jobs.running||0)+(overview.value.jobs.queued||0) : 0)
const selectedReady = computed(()=>selected.value.length>0)
const coverUrl = (a:any) => a.has_cover ? `/api/covers/${a.id}` : ''
const artists = (a:any) => (a?.artists||[]).join(' / ') || '待补充歌手'
const platformName = (p:string) => p==='netease'?'网易云':p==='tencent'?'QQ 音乐':p==='kuwo'?'酷我音乐':p==='apple'?'Apple Music':p==='spotify'?'Spotify':'本地'
function notify(text:string) {toast.value=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',4500)}
function addToQueue(items:any[]) {
  const result=enqueueSongs(items), notes=[]
  if(result.duplicates)notes.push(`跳过 ${result.duplicates} 首重复歌曲`)
  if(result.unavailable)notes.push(`跳过 ${result.unavailable} 首不可播放歌曲`)
  if(result.overflow)notes.push(`队列最多 1000 首，另有 ${result.overflow} 首未加入`)
  notify([result.added?`已加入 ${result.added} 首到播放队列`:'没有新增歌曲',...notes].join('；'))
}
async function act(label:string, task:()=>Promise<void>) { if(busy.value)return; busy.value=label;error.value='';try{await task()}catch(e){error.value=(e as Error).message}finally{busy.value=''} }
async function loadTab() {
  if(!logged.value||personalMode.value||user.value?.role!=='admin')return
  if(tab.value==='home') overview.value=await api('/overview')
  if(tab.value==='playlists') playlists.value=(await api('/playlists')).items
  if(tab.value==='jobs') { jobs.value=await api(`/jobs?state=${jobFilter.value}&page=${jobPage.value}`); if(!taskPolicy.value)taskPolicy.value={enabled:jobs.value.rate_limit.enabled,interval_seconds:jobs.value.rate_limit.interval_seconds,max_per_hour:jobs.value.rate_limit.max_per_hour} }
  if(tab.value==='library') {await Promise.all([
    api('/library/issues').then(d=>{scanIssues.value=d.items}),
    api('/playlists').then(d=>{playlists.value=d.items}),
    api(`/library?q=${encodeURIComponent(libraryQuery.value)}&filter=${libraryFilter.value}&page=${libraryPage.value}&folder=${encodeURIComponent(libraryFolder.value)}`).then(d=>{library.value=d})])}
  if(tab.value==='settings') {settings.value=await api('/settings');inbox.value=(await api('/inbox')).items;await loadSystem()}
  stale.value=false
}
async function loadSystem() {
  const s=await api('/system'); const at=Date.now()/1000
  if(previousCpu && at>previousCpu.time) cpu.value=Math.max(0,(s.cpu_seconds-previousCpu.seconds)/(at-previousCpu.time)*100)
  previousCpu={seconds:s.cpu_seconds,time:at};system.value=s
}
function navigate(next:string) {tab.value=next as Tab;error.value=''}
watch(tab, async()=>{try{await loadTab()}catch(e){error.value=(e as Error).message}})
async function login() {await act('正在登录',async()=>{const s=await api('/login','POST',{username:username.value,password:password.value});setCsrf(s.csrf);identity(s);password.value='';personalMode.value=true;logged.value=true})}
async function logout(){await act('正在退出',async()=>{await api('/logout','POST');stop(true);logged.value=false;setCsrf('')})}
async function openModal(name:string) {modal.value=name;await nextTick();dialog.value?.showModal()}
function closeModal(){dialog.value?.close();modal.value='';preview.value=null;showDiff.value=false;mappingConfirmed.value=false}
async function showAsset(a:any){await act('读取歌曲',async()=>{detail.value=await api(`/library/${a.id}/detail`);await openModal('asset')})}
async function showPlaylist(p:any){playlistVisible.value=100;await act('读取歌单',async()=>{playlistDetail.value=await api(`/playlists/${encodeURIComponent(p.id)}`);await openModal('playlist')})}
async function showJob(j:any){await act('读取记录',async()=>{jobDetail.value=await api(`/jobs/${j.id}`);await openModal('job')})}
async function findMusic(reset=true){await act('正在搜索',async()=>{if(reset)searchPage.value=1;const d=await api(`/search?q=${encodeURIComponent(query.value)}&platform=${platform.value}&page=${searchPage.value}`);searchResults.value=d.items;searched.value=true})}
async function chooseCandidate(t:any){playlists.value=(await api('/playlists')).items;if(targetPlaylist.value&&!playlists.value.some(p=>p.id===targetPlaylist.value))targetPlaylist.value='';candidate.value=t;mappingConfirmed.value=false;await openModal('candidate')}
async function confirmCandidate(){await act('正在加入',async()=>{
  const t=candidate.value
  if(linkedOriginal.value && linkedOriginal.value.key!==t.key) await api('/mappings','POST',{original:linkedOriginal.value.key,target:t.key,confirmed:mappingConfirmed.value})
  if(linkedAsset.value) {await api(`/library/${linkedAsset.value.id}`,'PATCH',{track_key:t.key});notify('已关联版本，可回音乐库补齐标签')}
  else if(linkedFile.value){const r=await api('/inbox/import','POST',{file:linkedFile.value.file,key:t.key,playlist_id:targetPlaylist.value||null});notify(r.existing?'库内已有此版本，无需重复入库':'已加入投递任务')}
  else {const r=await api('/acquire','POST',{key:t.key,playlist_id:targetPlaylist.value||null});notify(r.existing?'这个版本已在音乐库中':'已加入获取任务，后台会继续处理')}
  localStorage.setItem('music-target-playlist',targetPlaylist.value);closeModal();linkedAsset.value=null;linkedFile.value=null;linkedOriginal.value=null;overview.value=await api('/overview')
})}
function clearLink(){linkedAsset.value=null;linkedFile.value=null;linkedOriginal.value=null}
function matchFile(f:any){closeModal();clearLink();linkedFile.value=f;query.value=f.file.replace(/\.[^.]+$/,'');tab.value='search';searched.value=false;searchResults.value=[]}
function matchAsset(a:any){closeModal();clearLink();linkedAsset.value=a;query.value=a.title+' '+artists(a);tab.value='search';searched.value=false;searchResults.value=[]}
function matchOriginal(t:any){targetPlaylist.value=playlistDetail.value?.id||targetPlaylist.value;closeModal();clearLink();linkedOriginal.value=t;query.value=t.title+' '+artists(t);platform.value='netease';tab.value='search';searched.value=false;searchResults.value=[]}
async function previewShare(){await act('正在读取完整歌单',async()=>{preview.value=await api('/playlists/preview','POST',{text:share.value})})}
const importSchedule=ref('daily'), importRetention=ref('latest')
function selectChart(url:string){share.value=url;importSchedule.value='weekly_monday_0400';importRetention.value='append';importMode.value='all';autoAdd.value=true;previewShare()}
async function savePlaylistOptions(){await act('保存更新规则',async()=>{const p=playlistDetail.value;await api(`/playlists/${encodeURIComponent(p.id)}`,'PATCH',{schedule:p.schedule,retention:p.retention});playlistDetail.value=await api(`/playlists/${encodeURIComponent(p.id)}`);await loadTab()})}
async function addPlaylist(){await act('正在订阅',async()=>{const r=await api('/playlists','POST',{preview_id:preview.value.preview_id,mode:importMode.value,auto_add:autoAdd.value,schedule:importSchedule.value,retention:importRetention.value});notify(`已订阅歌单${r.queued?'，'+r.queued+' 首已加入任务':''}`);closeModal();share.value='';await loadTab()})}
async function refreshPlaylist(p:any){await act('加入检查任务',async()=>{await api(`/playlists/${encodeURIComponent(p.id)}/refresh`,'POST');notify('已加入检查任务，旧快照会保留到读取完整数据');closeModal()})}
async function changePlaylist(p:any,field:string){await act('保存歌单设置',async()=>{await api(`/playlists/${encodeURIComponent(p.id)}`,'PATCH',{[field]:!p[field]});p[field]=!p[field];notify('歌单设置已保存');await loadTab()})}
async function organizePlaylist(){await act('加入整理任务',async()=>{await api(`/playlists/${encodeURIComponent(playlistDetail.value.id)}/enrich`,'POST');notify('已加入分批整理，可靠匹配后补缺；不确定版本会单独标记');closeModal()})}
async function missingPlaylist(){await act('加入获取任务',async()=>{const r=await api(`/playlists/${encodeURIComponent(playlistDetail.value.id)}/missing`,'POST');notify(`${r.jobs.length} 首已加入任务`);closeModal()})}
async function scan(){await act('开始扫描',async()=>{await api('/library/scan','POST');notify('只读扫描已开始，结果会自动更新')})}
async function enrich(mode='all',ids=selected.value){await act('加入整理任务',async()=>{const r=await api('/library/enrich','POST',{asset_ids:ids,mode});notify(`${r.jobs.length} 首已加入整理任务`);selected.value=[];closeModal()})}
async function lockAsset(){await act('保存锁定状态',async()=>{await api(`/library/${detail.value.id}`,'PATCH',{locked:!detail.value.locked});detail.value.locked=!detail.value.locked;notify(detail.value.locked?'已锁定，后续整理会跳过':'已解锁')})}
async function filterLibrary(){libraryPage.value=1;selected.value=[];await act('筛选音乐',loadTab)}
async function actionJob(j:any,action:string){await act('更新任务',async()=>{await api(`/jobs/${j.id}/${action}`,'POST');notify('任务状态已更新');await loadTab();if(modal.value==='job')jobDetail.value=await api(`/jobs/${j.id}`)})}
async function pauseQueue(){await act('更新队列',async()=>{const value=!(jobs.value.queue_paused ?? overview.value?.queue_paused);await api('/settings','PATCH',{queue_paused:value});notify(value?'暂停领取新任务，当前歌曲会处理完':'队列已继续');await loadTab()})}
async function saveTaskPolicy(){await act('保存任务限流',async()=>{await api('/settings','PATCH',{task_policy:taskPolicy.value});notify('限流已保存，下次领取任务时生效');await loadTab()})}
async function updatePwa(){await act('正在更新界面缓存',async()=>{await refreshPwaCache();savePlayback();location.reload()})}
async function moveProvider(index:number,direction:number){const list=[...settings.value.providers];[list[index],list[index+direction]]=[list[index+direction],list[index]];await act('保存来源顺序',async()=>{await api('/settings','PATCH',{providers:list});settings.value.providers=list;notify('来源顺序已保存')})}
async function toggleProvider(p:string){const list=settings.value.providers.includes(p)?settings.value.providers.filter((x:string)=>x!==p):[...settings.value.providers,p];await act('保存来源',async()=>{await api('/settings','PATCH',{providers:list});settings.value.providers=list;notify('来源设置已保存')})}
async function uploadFiles(event:Event){const target=event.target as HTMLInputElement;const files=Array.from(target.files||[]);await act('正在上传音频',async()=>{for(const f of files){const form=new FormData();form.append('file',f);await api('/inbox/upload','POST',form)}inbox.value=(await api('/inbox')).items;notify('已放入投递箱，选定歌曲版本后即可入库')});target.value=''}
async function updatePassword(){await act('更改访问密码',async()=>{await api('/password','POST',{current:oldPassword.value,password:newPassword.value});oldPassword.value='';newPassword.value='';closeModal();stop(true);logged.value=false;notify('密码已更新，请重新登录')})}
const network=()=>{offline.value=!navigator.onLine}
const expired=()=>{stop(true);logged.value=false;error.value='登录已过期，请重新登录'}
const beforeInstall=(e:Event)=>{e.preventDefault();installPrompt.value=e}
async function install(){if(installPrompt.value){await installPrompt.value.prompt();installPrompt.value=null}else await openModal('install')}
onMounted(async()=>{
  window.addEventListener('online',network);window.addEventListener('offline',network);window.addEventListener('session-expired',expired);window.addEventListener('beforeinstallprompt',beforeInstall)
  try{const s=await api('/session');setCsrf(s.csrf||'');logged.value=s.authenticated;if(logged.value){identity(s);await loadTab()}}catch{error.value='暂时无法连接留声，请检查局域网连接'}finally{ready.value=true}
  timer=setInterval(async()=>{if(!logged.value||personalMode.value||document.hidden||busy.value||offline.value)return;try{if(['home','jobs','settings'].includes(tab.value))await loadTab();if(modal.value==='job')jobDetail.value=await api(`/jobs/${jobDetail.value.id}`)}catch{stale.value=true}},5000)
})
onUnmounted(()=>{clearInterval(timer);clearTimeout(toastTimer);window.removeEventListener('online',network);window.removeEventListener('offline',network);window.removeEventListener('session-expired',expired);window.removeEventListener('beforeinstallprompt',beforeInstall)})
</script>

<template>
  <div v-if="!ready" class="boot"><Disc3 :size="42"/><p>正在打开音乐库…</p></div>
  <main v-else-if="!logged" class="login-scene">
    <div class="login-art" aria-hidden="true"><div class="vinyl"><i></i></div><span>留住声音，留住喜欢。</span></div>
    <form class="login-card" @submit.prevent="login"><img src="/icon.svg" width="52" height="52" alt="留声标志"><h1>欢迎回到留声</h1><label>用户名<input v-model="username" autocomplete="username" maxlength="40" required></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required autofocus placeholder="输入你的密码"></label><p v-if="error" class="inline-error" role="alert">{{error}}</p><button class="primary wide" :disabled="!!busy"><LoaderCircle v-if="busy" class="spin" :size="17"/>{{busy||'打开音乐库'}}</button><details class="fine"><summary>登录帮助</summary><p>管理员用户名为 admin，密码为原访问密码。其他账号由管理员创建。</p></details></form>
  </main>
  <PersonalHub v-else-if="personalMode" :user="user" @manage="manage" @logout="logout"/>
  <div v-else class="app-shell" :class="{'has-player':player.index>=0}">
    <aside class="sidebar"><a class="brand" href="#" @click.prevent="navigate('home')"><img src="/icon.svg" alt=""/><span>留声<small>个人音乐库</small></span></a><nav aria-label="主要导航"><button v-for="item in tabs" :key="item.id" :class="{active:tab===item.id}" :aria-current="tab===item.id?'page':undefined" @click="navigate(item.id)"><component :is="item.icon" :size="21"/><span>{{item.label}}</span><em v-if="item.id==='jobs' && activeCount">{{activeCount}}</em></button></nav><div class="sidebar-bottom"><p><span class="status-dot" :class="{offline}"></span>{{offline?'网络已断开':'私人收藏 · NAS'}}</p><button class="plain" :class="{selected:tab==='settings'}" @click="navigate('settings')"><Settings :size="18"/>设置与运行状态</button><small>LIUSHENG / {{version}}</small></div></aside>
    <div class="workspace">
      <div class="topbar"><div class="mobile-brand"><img src="/icon.svg" alt=""/>留声</div><span class="desktop-crumb">个人音乐库 <ChevronRight :size="13"/>{{tabs.find(x=>x.id===tab)?.label||'设置'}}</span><div class="top-actions"><span v-if="busy" class="busy-label"><LoaderCircle class="spin" :size="14"/>{{busy}}</span><button class="icon-button" aria-label="安装与主屏幕说明" @click="install"><Download :size="18"/></button><button class="icon-button" aria-label="设置" @click="navigate('settings')"><Settings :size="19"/></button></div></div>
      <div v-if="offline||stale" class="network-note" role="status">{{offline?'网络已断开':'暂时无法连接服务'}}。当前显示的是上次结果，恢复连接后再操作。</div>
      <div v-if="error" class="error-banner" role="alert"><CircleAlert :size="19"/><span>{{error}}</span><button aria-label="关闭错误提示" class="icon-button" @click="error='' "><X :size="17"/></button></div>
      <button class="secondary compact" @click="personalMode=true">返回个人音乐</button><header class="page-header"><div><h1>{{titles[tab]}}</h1><p class="muted">{{descriptions[tab]}}</p></div><button v-if="tab==='home'||tab==='search'" class="primary" @click="tab==='home'?navigate('search'):openModal('share')"><Plus :size="18"/>{{tab==='home'?'添加音乐':'粘贴歌单'}}</button><button v-if="tab==='playlists'" class="primary" @click="openModal('share')"><Plus :size="18"/>订阅歌单</button><button v-if="tab==='library'" class="secondary" :disabled="!!busy" @click="scan"><RefreshCw :size="17"/>扫描音乐库</button><button v-if="tab==='jobs'" class="secondary" @click="pauseQueue"><component :is="jobs.queue_paused?Play:Pause" :size="17"/>{{jobs.queue_paused?'继续队列':'暂停队列'}}</button></header>

      <section v-if="tab==='home' && overview" class="home-content">
        <div class="collection-panel"><div class="collection-copy"><span class="small-label">已经留下的喜欢</span><div class="collection-number">{{overview.assets.toLocaleString()}}<span>首音乐</span></div><p>{{bytes(overview.bytes)}} · {{overview.playlists}} 张歌单</p><button class="text-button" @click="navigate('library')">走进音乐库 <ArrowUpRight :size="18"/></button></div><div class="record-sleeves" aria-hidden="true"><div v-for="(a,i) in overview.recent.slice(0,4)" :key="a.id" class="sleeve" :style="{'--i':i}"><img v-if="a.has_cover" :src="coverUrl(a)" alt=""><div v-else class="sleeve-placeholder"><Music2 :size="34"/><span>{{a.title.slice(0,8)}}</span></div></div><div v-if="!overview.recent.length" class="empty-record"><Disc3 :size="100"/></div></div></div>
        <div class="overview-grid"><button class="metric-card" @click="navigate('jobs')"><span class="metric-icon indigo"><Activity :size="22"/></span><div><span class="muted">正在等待 / 处理</span><strong>{{activeCount}}<small>个任务</small></strong></div><ChevronRight :size="17"/></button><button class="metric-card" @click="libraryFilter='lyrics';navigate('library')"><span class="metric-icon teal"><FileMusic :size="22"/></span><div><span class="muted">还可以补上歌词</span><strong>{{overview.missing_lyrics}}<small>首音乐</small></strong></div><ChevronRight :size="17"/></button><button class="metric-card" @click="jobFilter='failed';navigate('jobs')"><span class="metric-icon amber"><CircleAlert :size="22"/></span><div><span class="muted">需要你看一眼</span><strong>{{overview.jobs.failed||0}}<small>个任务</small></strong></div><ChevronRight :size="17"/></button></div>
        <div class="section-title"><h2>最近入库</h2><button class="text-button" @click="navigate('library')">查看全部 <ChevronRight :size="16"/></button></div>
        <div v-if="overview.recent.length" class="album-grid"><button v-for="a in overview.recent" :key="a.id" class="album-tile" @click="showAsset(a)"><div class="album-art"><img v-if="a.has_cover" :src="coverUrl(a)" alt="" loading="lazy"><Music2 v-else :size="36"/><span>{{a.format}}</span></div><strong>{{a.title}}</strong><span>{{artists(a)}}</span></button></div>
        <div v-else class="empty"><Library :size="40"/><h3>从已有音乐开始</h3><p>扫描配置好的 NAS 目录，查看标签、封面和歌词。</p><button class="primary" @click="scan">扫描音乐库</button></div>
        <div class="section-title"><h2>整理动态</h2><button class="text-button" @click="navigate('jobs')">全部任务 <ChevronRight :size="16"/></button></div><div class="panel"><div v-if="!overview.active.length" class="quiet-row"><Check :size="20"/><span>目前没有待处理任务。挑一张歌单，或者补齐几首歌词。</span></div><button v-for="j in overview.active" :key="j.id" class="activity-row" @click="showJob(j)"><span class="state-icon" :class="j.state"><LoaderCircle v-if="j.state==='running'" class="spin" :size="18"/><CircleAlert v-else-if="['failed','review'].includes(j.state)" :size="18"/><Clock3 v-else :size="18"/></span><div><strong>{{j.title}}</strong><small>{{j.error||j.stage}}</small></div><span class="badge" :class="j.state">{{stateNames[j.state]}}</span></button></div>
      </section>

      <section v-if="tab==='playlists'">
        <div class="info-strip"><RefreshCw :size="18"/><p>每张歌单可设置每日或每周检查；热门榜单默认每周一 04:00 更新，成员只增不减。</p></div>
        <div v-if="!playlists.length" class="empty"><ListMusic :size="44"/><h3>让收藏跟上歌单的变化</h3><p>选择热门榜单，或粘贴支持平台的歌单链接。</p><button class="primary" @click="openModal('share')">粘贴歌单链接</button></div>
        <div class="playlist-grid"><article v-for="p in playlists" :key="p.id" class="playlist-card"><button class="playlist-main" @click="showPlaylist(p)"><div class="playlist-art"><img v-if="p.cover" :src="p.cover" referrerpolicy="no-referrer" alt="" loading="lazy"><ListMusic v-else :size="40"/><span>{{platformName(p.platform)}}</span></div><h2>{{p.name}}</h2><p>{{p.count}} 首 · 库内已有 {{p.available}} 首</p></button><div class="coverage"><span :style="{width:(p.available/Math.max(p.count,1)*100)+'%'}"></span></div><div class="playlist-meta"><span>{{p.platform==='local'?'本地文件夹':p.enabled?'自动检查已开启':'手动检查'}}</span><small>{{date(p.last_check)}}</small></div><p v-if="p.last_error" class="inline-error">{{p.last_error}}</p><div class="playlist-footer"><button class="text-button" @click="showPlaylist(p)">{{p.platform==='local'?'查看歌曲':'查看变化'}} <ChevronRight :size="15"/></button><button class="icon-button" aria-label="立即检查歌单" @click="refreshPlaylist(p)"><RefreshCw :size="17"/></button></div></article><button class="add-playlist" @click="openModal('share')"><Plus :size="32"/><span>再收藏一张歌单</span></button></div>
      </section>

      <section v-if="tab==='search'">
        <div v-if="linkedFile||linkedAsset||linkedOriginal" class="info-strip"><FileMusic :size="20"/><p>正在为 <strong>{{linkedFile?.file||linkedAsset?.title||linkedOriginal?.title}}</strong> 选择对应录音版本。</p><button class="icon-button" aria-label="取消关联" @click="clearLink"><X :size="18"/></button></div>
        <form class="search-box" @submit.prevent="findMusic()"><Search :size="23"/><input v-model="query" aria-label="歌名和歌手" placeholder="歌名 + 歌手，例如：PLANET ラムジ" required maxlength="160"><select v-model="platform" aria-label="搜索平台"><option value="netease">网易云</option><option value="tencent">QQ 音乐</option><option value="kuwo">酷我音乐</option></select><button class="primary" :disabled="!!busy">{{busy==='正在搜索'?'查找中…':'搜索'}}</button></form>
        <p class="fine search-hint">歌名相同也可能是不同演唱。确认歌手、专辑、版本和时长后再入库。</p>
        <div v-if="!searched" class="search-welcome"><div class="search-record"><Disc3 :size="76" stroke-width="1"/></div><h2>今天，想留下哪首歌？</h2><p>从平时听歌的 App 记下歌名。<br>也可以粘贴一张歌单，让留声帮你对照音乐库。</p><button class="text-button" @click="openModal('share')">我有一个歌单链接 <ArrowUpRight :size="17"/></button></div>
        <template v-else><div class="section-title"><h2>搜索结果 <span>{{searchResults.length}} 个候选</span></h2><span class="fine">第 {{searchPage}} 页</span></div><div v-if="!searchResults.length" class="empty"><Search :size="36"/><h3>还没找到匹配结果</h3><p>试试缩短歌名，补上歌手，或切换搜索平台。</p></div><div class="panel track-list"><div v-for="t in searchResults" :key="t.key" class="track-row"><div class="track-cover"><img v-if="t.cover" :src="t.cover" alt="" referrerpolicy="no-referrer" loading="lazy"><Music2 v-else :size="23"/></div><div class="track-title"><strong>{{t.title}}</strong><span>{{artists(t)}}</span><small class="mobile-only">{{t.album}} · {{duration(t.duration)}}</small></div><span class="track-album">{{t.album||'专辑待补充'}}</span><span class="track-duration">{{duration(t.duration)}}</span><button class="icon-button" :aria-label="'试听 '+t.title" @click="playSongs([t])"><Play :size="18"/></button><button class="secondary compact" @click="chooseCandidate(t)"><Check v-if="t.asset_id" :size="15"/><Plus v-else :size="15"/>{{t.asset_id?'已有':'选择'}}</button></div></div><div class="pagination"><button class="secondary" :disabled="searchPage<=1||!!busy" @click="searchPage--;findMusic(false)"><ChevronLeft :size="16"/>上一页</button><button class="secondary" :disabled="searchResults.length<20||!!busy" @click="searchPage++;findMusic(false)">下一页<ChevronRight :size="16"/></button></div></template>
      </section>

      <section v-if="tab==='jobs'">
        <div v-if="jobs.summary" class="task-summary" aria-label="任务统计">
          <div><small>全部任务</small><strong>{{jobs.summary.total}}</strong></div><div><small>等待中</small><strong>{{jobs.summary.states.queued||0}}</strong></div><div><small>处理中</small><strong>{{jobs.summary.states.running||0}}</strong></div><div><small>已完成</small><strong>{{jobs.summary.states.succeeded||0}}</strong></div><div><small>失败 / 待确认</small><strong>{{jobs.summary.states.failed||0}} / {{jobs.summary.states.review||0}}</strong></div><div><small>近 24 小时完成</small><strong>{{jobs.summary.finished_last_day}}</strong></div>
          <p class="fine">全局统计，不受下方筛选影响。平均执行耗时 {{elapsed(jobs.summary.average_seconds)}}；仅统计有完整计时的成功任务；旧任务缺失时间不计入近 24 小时。</p>
        </div>
        <details v-if="jobs.rate_limit&&taskPolicy" class="panel task-throttle"><summary>任务限流 · {{jobs.rate_limit.enabled?'每小时最多 '+jobs.rate_limit.max_per_hour+' 次，间隔 '+jobs.rate_limit.interval_seconds+' 秒':'已关闭'}} · 当前单任务处理</summary>
          <p class="fine">近一小时启动 {{jobs.rate_limit.starts_last_hour}} 次。{{jobs.rate_limit.wait_seconds?'因'+jobs.rate_limit.reason+'，最早 '+taskDate(jobs.rate_limit.next_allowed_at)+' 可领取下一项。':'当前额度可用。'}}不打断正在处理的歌曲，不限制网页播放。</p>
          <form class="throttle-form" @submit.prevent="saveTaskPolicy"><label class="radio-line"><input type="checkbox" v-model="taskPolicy.enabled">开启任务限流</label><label>启动间隔（秒）<input aria-label="任务启动间隔" type="number" min="0" max="3600" step="1" v-model.number="taskPolicy.interval_seconds" required></label><label>滚动一小时上限<input aria-label="每小时任务上限" type="number" min="1" max="3600" step="1" v-model.number="taskPolicy.max_per_hour" required></label><button class="secondary" :disabled="!!busy">保存限流</button></form><p class="fine">重试也占用额度；来源请求间隔和错误冷却仍然生效。等待中包括限流、重试等待和普通排队任务。</p>
        </details>

        <div v-if="jobs.queue_paused" class="info-strip"><Pause :size="18"/><p>队列已暂停领取新任务。正在处理的歌曲会完成当前任务。</p></div><div class="filter-bar"><button v-for="[id,label] in [['all','全部'],['running','处理中'],['queued','等待中'],['failed','需要处理'],['succeeded','已完成'],['review','待确认版本'],['paused','已暂停']]" :key="id" :class="{chosen:jobFilter===id}" @click="jobFilter=id;jobPage=1;act('读取任务',loadTab)">{{label}}</button></div>
        <div v-if="!jobs.items.length" class="empty"><ListChecks :size="42"/><h3>这里暂时没有任务</h3><p>添加音乐、检查歌单或补齐歌词后，都能在这里查看进度。</p></div><div class="job-cards"><article v-for="j in jobs.items" :key="j.id" class="job-card"><button class="job-info" @click="showJob(j)"><span class="state-icon" :class="j.state"><Check v-if="j.state==='succeeded'" :size="22"/><LoaderCircle v-else-if="j.state==='running'" :size="22" class="spin"/><CircleAlert v-else-if="['failed','review'].includes(j.state)" :size="22"/><Clock3 v-else :size="22"/></span><div><h3>{{j.title}}</h3><p :class="{'error-text':j.error}">{{j.error||j.stage}}</p><small>加入 {{taskDate(j.created)}}</small></div><span class="badge" :class="j.state">{{stateNames[j.state]}}</span></button><div v-if="j.state==='running'" class="progress-track"><i :style="{width:j.progress+'%'}"></i></div><div class="job-timing"><span>开始 {{taskDate(j.started_at)}}</span><span>{{j.state==='succeeded'?'完成':'结束'}} {{taskDate(j.finished_at)}}</span><span>{{j.timing_partial?'已记录耗时':'执行耗时'}} {{elapsed(j.elapsed_seconds)}}</span></div><div class="job-actions"><button class="text-button" @click="showJob(j)">查看记录 <ChevronRight :size="14"/></button><button v-if="['queued','running'].includes(j.state)" class="text-button" @click="actionJob(j,'pause')">暂停</button><button v-if="['failed','paused','cancelled','review'].includes(j.state)" class="text-button" @click="actionJob(j,'retry')">{{j.state==='paused'?'继续':'重试'}}</button><button v-if="['queued','running','paused'].includes(j.state)" class="text-button" @click="actionJob(j,'cancel')">取消</button></div></article></div><div v-if="jobs.total>40" class="pagination"><button class="secondary" :disabled="jobPage<=1" @click="jobPage--;act('读取任务',loadTab)">上一页</button><span>{{jobPage}} / {{Math.ceil(jobs.total/40)}}</span><button class="secondary" :disabled="jobPage*40>=jobs.total" @click="jobPage++;act('读取任务',loadTab)">下一页</button></div>
      </section>

      <section v-if="tab==='library'"><details v-if="scanIssues.length" class="panel settings-panel"><summary>{{scanIssues.length}} 个文件无法识别，已保留原文件</summary><p v-for="issue in scanIssues" :key="issue.path" class="fine">{{issue.path}} · {{issue.error}}</p></details>
        <div class="library-toolbar"><select v-model="libraryFolder" aria-label="按歌单文件夹筛选" @change="filterLibrary"><option value="">全部文件夹</option><option v-for="p in playlists" :key="p.id" :value="p.folder">{{p.name}}</option></select><form class="small-search" @submit.prevent="filterLibrary"><Search :size="18"/><input v-model="libraryQuery" aria-label="搜索音乐库" placeholder="搜索歌曲、歌手或专辑"><button class="text-button">查找</button></form><div class="select-wrap"><SlidersHorizontal :size="17"/><select v-model="libraryFilter" aria-label="按缺失项筛选" @change="filterLibrary"><option value="all">全部音乐</option><option value="incomplete">需要补齐</option><option value="lyrics">缺少歌词</option><option value="cover">缺少封面</option><option value="missing">文件失踪</option><option value="review">待确认版本</option></select></div><button class="secondary compact" :disabled="!library.items.some((a:any)=>a.present)" @click="playSongs(library.items)"><Play :size="15"/>播放本页</button><span class="count-label">{{library.total}} 首</span></div>
        <div v-if="selectedReady" class="selection-bar"><strong>已选 {{selected.length}} 首</strong><button class="secondary compact" :disabled="!!busy" @click="enrich('all')">补齐缺失项</button><button class="text-button" :disabled="!!busy" @click="enrich('lyrics')">只补歌词</button><button class="icon-button" aria-label="取消选择" @click="selected=[]"><X :size="18"/></button></div>
        <div v-if="!library.items.length" class="empty"><Library :size="40"/><h3>{{libraryFilter==='all'?'还没有匹配的音乐':'这一项已经很整齐了'}}</h3><p>可以调整筛选，或重新扫描音乐库。</p></div><div v-else class="panel library-list"><div class="list-labels"><label><input type="checkbox" aria-label="选择本页可整理歌曲" :checked="library.items.filter((a:any)=>a.present&&!a.locked).length>0&&library.items.filter((a:any)=>a.present&&!a.locked).every((a:any)=>selected.includes(a.id))" @change="selected=($event.target as HTMLInputElement).checked?library.items.filter((a:any)=>a.present&&!a.locked).map((a:any)=>a.id):[]"></label><span>歌曲 / 歌手</span><span class="track-album">专辑</span><span class="library-state">整理状态</span><span></span></div><div v-for="a in library.items" :key="a.id" class="library-row"><input v-model="selected" :value="a.id" type="checkbox" :aria-label="'选择 '+a.title" :disabled="a.locked||!a.present"><button class="library-song" @click="showAsset(a)"><div class="track-cover"><img v-if="a.has_cover" :src="coverUrl(a)" alt="" loading="lazy"><Music2 v-else :size="22"/></div><div class="track-title"><strong>{{a.title}}</strong><span>{{artists(a)}}</span></div></button><span class="track-album">{{a.album||'专辑待补充'}}</span><div class="library-state"><span v-if="a.locked" class="badge"><LockKeyhole :size="12"/>已锁定</span><span v-else-if="!a.present" class="badge failed">文件失踪</span><span v-else-if="a.match_status==='needs_review'" class="badge pending">待确认版本</span><span v-else-if="!a.missing.length" class="badge succeeded"><Check :size="12"/>已补齐</span><span v-else class="badge pending">缺{{a.missing.length}}项</span><small>{{a.format}} · {{duration(a.duration)}}</small></div><div class="row-play-actions"><button class="icon-button" :disabled="!a.present" :aria-label="'播放 '+a.title" @click="playSongs([a])"><Play :size="18"/></button><button class="icon-button" :disabled="!a.present" :aria-label="'加入队列 '+a.title" @click="addToQueue([a])"><Plus :size="17"/></button></div></div></div><div v-if="library.total>40" class="pagination"><button class="secondary" :disabled="libraryPage<=1" @click="libraryPage--;selected=[];act('读取音乐',loadTab)"><ChevronLeft :size="16"/>上一页</button><span>{{libraryPage}} / {{Math.ceil(library.total/40)}}</span><button class="secondary" :disabled="libraryPage*40>=library.total" @click="libraryPage++;selected=[];act('读取音乐',loadTab)">下一页<ChevronRight :size="16"/></button></div>
      </section>

      <section v-if="tab==='settings' && settings" class="settings-grid">
        <article class="panel settings-panel"><div class="section-title"><h2><Activity :size="20"/>运行状态</h2><span class="badge" :class="system?.worker_alive?'succeeded':'failed'">{{system?.worker_alive?'后台正常':'需要检查'}}</span></div><div v-if="system" class="system-grid"><div><small>容器内存</small><strong>{{bytes(system.container_memory_bytes||system.process_memory_bytes)}}</strong><span>{{system.memory_limit_bytes?'上限 '+bytes(system.memory_limit_bytes):'当前应用进程'}}</span></div><div><small>应用 CPU</small><strong>{{cpu===null?'采样中':cpu.toFixed(1)+'%'}}</strong><span>按单个 CPU 核心计</span></div><div><small>曲库可用空间</small><strong>{{bytes(system.disk_free_bytes)}}</strong><span>处理并发 {{system.audio_concurrency}}</span></div><div><small>已连续运行</small><strong>{{Math.floor(system.uptime_seconds/3600)}}h {{Math.floor(system.uptime_seconds%3600/60)}}m</strong><span>版本 {{system.version}}</span></div></div><p class="fine">Compose 容器可在现有监控工具中查看完整 CPU、内存和 I/O。页面 CPU 为应用进程采样。</p></article>
        <article class="panel settings-panel"><div class="section-title"><h2><ListChecks :size="20"/>音频来源</h2></div><p class="muted">按顺序尝试，完整音频验证成功后停止。来源故障与未找到会分别记录。</p><div v-for="(p,i) in settings.providers" :key="p" class="provider-row"><span class="provider-order">{{Number(i)+1}}</span><strong>{{providerNames[p]}}</strong><button class="icon-button" :disabled="i===0" :aria-label="'上移 '+providerNames[p]" @click="moveProvider(Number(i),-1)"><ArrowUp :size="16"/></button><button class="icon-button" :disabled="i===settings.providers.length-1" :aria-label="'下移 '+providerNames[p]" @click="moveProvider(Number(i),1)"><ArrowDown :size="16"/></button><button class="text-button" @click="toggleProvider(p)">停用</button></div><button v-for="p in settings.available_providers.filter((x:string)=>!settings.providers.includes(x))" :key="p" class="text-button" @click="toggleProvider(p)">启用 {{providerNames[p]}}</button><div class="health-lines"><p v-for="s in settings.source_health" :key="s.source"><span class="status-dot" :class="{offline:s.status!=='ok'}"></span><strong>{{providerNames[s.source]||s.source}}</strong><span>{{s.detail}}</span><small>{{date(s.checked)}}</small></p></div></article>
        <SourceManager :settings="settings" @refresh="loadTab"/><article class="panel settings-panel full-width"><div class="section-title"><h2><Upload :size="20"/>本地投递箱</h2><label class="secondary upload-button"><Plus :size="17"/>选择音频<input type="file" accept=".flac,.mp3,.m4a,.ogg,.opus,.wav,.ape" multiple @change="uploadFiles" :disabled="!!busy"></label></div><p class="muted">把自己保存的音频投递到这里，再搜索并选定对应版本。原投递文件会保留。</p><div v-if="!inbox.length" class="inbox-empty"><FileMusic :size="30"/><p>等待你带回一首歌</p><small>支持 FLAC、MP3、M4A 等文件；标签写入按格式能力处理。</small></div><div v-for="f in inbox" :key="f.file" class="inbox-row"><FileMusic :size="22"/><div><strong>{{f.file}}</strong><small>{{bytes(f.size)}}</small></div><button class="secondary compact" @click="matchFile(f)">选择版本</button></div><details class="subtle-details" open><summary>人工资源入口与投递位置</summary><p>以下入口尚未接入自动下载。手动保存文件后投递，不会把未访问的来源记为“未找到”。</p><div class="resource-links"><a v-for="s in settings.manual_sources" :key="s.name" :href="s.url" target="_blank" rel="noopener noreferrer">{{s.name}}<ArrowUpRight :size="14"/><small>{{s.detail}}</small></a></div><p class="fine">容器内投递目录：{{settings.inbox_path}}</p></details></article>
        <article class="panel settings-panel"><h2>平台接入</h2><div v-for="p in settings.platforms" :key="p.id" class="platform-row"><strong>{{p.name}}</strong><p>{{p.detail}}</p></div><p class="fine">当前支持公开内容。私有歌单或需要会员凭据的来源可能返回不可用，不会使用试听片段代替整曲。</p></article>
        <article class="panel settings-panel"><h2>访问与使用</h2><button class="settings-link" @click="install"><Download :size="19"/><span>添加到主屏幕</span><ChevronRight :size="16"/></button><button class="settings-link" @click="openModal('password')"><LockKeyhole :size="19"/><span>更改访问密码</span><ChevronRight :size="16"/></button><button class="settings-link" @click="openModal('pwa-update')"><RefreshCw :size="19"/><span>手动更新 PWA 缓存</span><ChevronRight :size="16"/></button><button class="settings-link" @click="logout"><LogOut :size="19"/><span>退出登录</span><ChevronRight :size="16"/></button><p class="fine">{{secure?'当前为可信连接，可使用 PWA 离线界面。':'当前通过局域网 HTTP 访问，管理功能正常；主屏幕安装与离线界面需要可信 HTTPS。'}}</p><p class="fine">支持搜索试听与音乐库播放；音频需要联网。歌词和队列可在底部播放器展开查看。</p></article>
      </section>
      <footer class="page-footer"><span>留声 · 让收藏有处安放</span><span>v{{version}}</span></footer>
    </div>
    <nav class="bottom-nav" aria-label="手机导航"><button v-for="item in tabs" :key="item.id" :class="{active:tab===item.id}" :aria-current="tab===item.id?'page':undefined" @click="navigate(item.id)"><component :is="item.icon" :size="21"/><span>{{item.label}}</span><i v-if="item.id==='jobs'&&activeCount"></i></button></nav>
  </div>
  <Player v-if="logged"/>
  <div v-if="toast" class="toast" role="status"><Check :size="18"/>{{toast}}</div>
  <dialog ref="dialog" class="modal" :class="{'large-modal':modal==='playlist'}" @cancel="closeModal" @click="($event.target===dialog)&&closeModal()">
    <div v-if="modal" class="modal-content"><button class="close-modal icon-button" aria-label="关闭弹窗" @click="closeModal"><X :size="22"/></button><p v-if="error" class="inline-error" role="alert">{{error}}</p>
      <template v-if="modal==='share'"><ChartSubscriptions @select="selectChart"/><p class="eyebrow">从发现，到收藏</p><h2>订阅一张歌单</h2><p class="muted">粘贴网易云、QQ、Apple Music 中国大陆或 Spotify 的歌单链接。</p><form @submit.prevent="previewShare"><textarea v-model="share" rows="3" placeholder="分享歌单：… https://163cn.tv/…" aria-label="歌单分享文本" required></textarea><button class="secondary wide" :disabled="!!busy">{{busy==='正在读取完整歌单'?'正在读取完整歌单…':'读取歌单'}}</button></form><div v-if="preview" class="preview-box"><h3>{{preview.name}}</h3><p>{{preview.count}} 首 · 库内已有 {{preview.existing}} 首</p><label class="radio-line"><input v-model="importMode" type="radio" value="watch">先建立快照，只关注后续变化</label><label class="radio-line"><input v-model="importMode" type="radio" value="all">把当前缺少的歌曲加入获取任务</label><label class="radio-line"><input v-model="autoAdd" type="checkbox">以后检查到新增歌曲时自动获取</label><label class="field-label">更新规则<select v-model="importSchedule"><option value="manual">手动检查</option><option value="daily">每天检查</option><option value="weekly_monday_0400">每周一 04:00</option></select></label><label class="field-label">成员保留<select v-model="importRetention"><option value="latest">跟随当前歌单，音乐文件保留</option><option value="append">只增不减，歌单和文件都保留</option></select></label><button class="primary wide" :disabled="!!busy" @click="addPlaylist">确认订阅</button></div></template>
      <template v-if="modal==='candidate' && candidate"><p class="eyebrow">确认要留下的版本</p><h2>{{candidate.title}}</h2><p class="muted">{{artists(candidate)}}</p><button class="secondary wide" @click="playSongs([candidate]);closeModal()"><Play :size="17"/>{{candidate.asset_id?'播放库内版本':'先试听这个版本'}}</button><label v-if="!linkedAsset" class="field-label">保存到歌单<select v-model="targetPlaylist" aria-label="保存到歌单"><option value="">手动收藏 / 上次使用</option><option v-for="p in playlists" :key="p.id" :value="p.id">{{p.name}}</option></select></label><dl class="detail-grid"><dt>专辑</dt><dd>{{candidate.album||'待补充'}}</dd><dt>时长</dt><dd>{{duration(candidate.duration)}}</dd><dt>平台</dt><dd>{{platformName(candidate.platform)}}</dd><dt>音质</dt><dd>获取后实测，不将来源声明当成实测结果</dd></dl><div v-if="linkedOriginal && linkedOriginal.key!==candidate.key" class="mapping-warning"><p>原条目：{{linkedOriginal.title}} · {{artists(linkedOriginal)}} · {{duration(linkedOriginal.duration)}}</p><label class="radio-line"><input v-model="mappingConfirmed" type="checkbox">我确认这是同一个录音版本</label></div><p class="fine">{{linkedFile?'此文件将复制、整理后入库，原投递文件保留。':linkedAsset?'只建立对应关系，补齐标签需要随后在音乐库执行。':'已有同版本文件会直接复用；缺失时按来源顺序获取。'}}</p><button class="primary wide" :disabled="!!busy||!!(linkedOriginal&&linkedOriginal.key!==candidate.key&&!mappingConfirmed)" @click="confirmCandidate">{{linkedFile?'确认并整理入库':linkedAsset?'确认关联':candidate.asset_id?'使用已有版本':'确认并加入任务'}}</button></template>
      <template v-if="modal==='asset' && detail"><div class="asset-heading"><div class="detail-cover"><img v-if="detail.has_cover" :src="coverUrl(detail)" alt=""><Music2 v-else :size="38"/></div><div><p class="eyebrow">{{detail.format}} · {{duration(detail.duration)}}</p><h2>{{detail.title}}</h2><p class="muted">{{artists(detail)}}</p></div></div><div class="button-row"><button class="primary" :disabled="!detail.present" @click="playSongs([detail]);closeModal()"><Play :size="17"/>播放</button><button class="secondary" :disabled="!detail.present" @click="addToQueue([detail])"><Plus :size="17"/>加入队列</button></div><dl class="detail-grid"><dt>专辑</dt><dd>{{detail.album||'待补充'}}</dd><dt>来源</dt><dd>{{providerNames[detail.source]||detail.source}}</dd><dt>歌词</dt><dd>{{detail.lyrics_status}}</dd><dt>待补齐</dt><dd>{{detail.missing.join('、')||'基础信息完整'}}</dd><dt>文件</dt><dd class="file-path">{{detail.path}}</dd><dt>大小</dt><dd>{{bytes(detail.size)}}</dd></dl><div class="button-row"><button v-if="detail.track_key" class="primary" :disabled="detail.locked||!!busy" @click="enrich('all',[detail.id])">补齐缺失项</button><button v-else class="primary" @click="matchAsset(detail)">关联歌曲版本</button><button class="secondary" @click="lockAsset"><LockKeyhole :size="16"/>{{detail.locked?'解除锁定':'锁定修正'}}</button></div><details v-if="detail.lyrics_text" class="lyrics-details"><summary>查看已保存歌词</summary><pre>{{detail.lyrics_text}}</pre></details></template>
      <template v-if="modal==='playlist' && playlistDetail"><p class="eyebrow">{{platformName(playlistDetail.platform)}} · {{playlistDetail.count}} 首</p><h2>{{playlistDetail.name}}</h2><p class="fine">文件夹：{{playlistDetail.folder}}</p><p class="muted">库内已有 {{playlistDetail.available}} 首 · 最近完整检查 {{date(playlistDetail.last_check)}}</p><div class="button-row"><button class="primary" :disabled="!playlistDetail.available" @click="playSongs(playlistDetail.tracks.filter((t:any)=>t.asset_id));closeModal()"><Play :size="16"/>播放库内 {{playlistDetail.available}} 首</button><button class="secondary" :disabled="!playlistDetail.available" @click="addToQueue(playlistDetail.tracks.filter((t:any)=>t.asset_id));closeModal()"><Plus :size="16"/>加入播放队列</button><button class="secondary" @click="refreshPlaylist(playlistDetail)"><RefreshCw :size="16"/>立即检查</button><button class="secondary" :disabled="!!busy" @click="organizePlaylist">补齐歌单</button><a class="secondary" :href="`/api/playlists/${encodeURIComponent(playlistDetail.id)}/export`"><Download :size="16"/>导出列表</a><button v-if="playlistDetail.platform!=='local'" class="secondary" :disabled="!!busy" @click="missingPlaylist">获取缺少的 {{playlistDetail.count-playlistDetail.available}} 首</button></div><p class="fine">加入播放队列会把库内歌曲追加到末尾，保留当前播放；同一库内版本不重复加入。</p><div class="playlist-switches"><label v-if="playlistDetail.platform!=='local' && playlistDetail.schedule!=='manual'"><input type="checkbox" :checked="!!playlistDetail.enabled" @change="changePlaylist(playlistDetail,'enabled')">启用定时检查</label><label v-if="playlistDetail.platform!=='local'"><input type="checkbox" :checked="!!playlistDetail.auto_add" @change="changePlaylist(playlistDetail,'auto_add')">新增时自动获取</label></div><div v-if="playlistDetail.platform!=='local'" class="playlist-switches"><label>更新规则<select v-model="playlistDetail.schedule" @change="savePlaylistOptions"><option value="manual">手动检查</option><option value="daily">每天检查</option><option value="weekly_monday_0400">每周一 04:00</option></select></label><label>成员保留<select v-model="playlistDetail.retention" @change="savePlaylistOptions"><option value="latest">跟随当前榜单</option><option value="append">只增不减</option></select></label></div><p v-if="playlistDetail.platform!=='local'" class="fine">当前在榜 {{playlistDetail.current_count}} 首 · 累计 {{playlistDetail.count}} 首 · 待匹配 {{playlistDetail.pending_match}} 首 · 获取失败 {{playlistDetail.download_failed}} 首 · 下次检查 {{playlistDetail.enabled?date(playlistDetail.next_check):'已暂停'}}</p><p v-if="playlistDetail.last_error" class="inline-error">{{playlistDetail.last_error}}</p><div class="filter-bar"><button :class="{chosen:!showDiff}" @click="showDiff=false">全部歌曲</button><button :class="{chosen:showDiff}" @click="showDiff=true">最近变化</button></div><div v-if="showDiff" class="diff-content"><p v-if="!(playlistDetail.diff.added?.length||playlistDetail.diff.removed?.length||playlistDetail.diff.reordered)" class="quiet-row">最近没有成员变化。</p><p v-if="playlistDetail.diff.reordered">歌单顺序已更新，未重复获取音乐。</p><p v-for="t in playlistDetail.diff.added||[]" :key="'a'+t.key"><span class="badge succeeded">新增</span>{{t.title}} · {{artists(t)}}</p><p v-for="t in playlistDetail.diff.removed||[]" :key="'r'+t.key"><span class="badge pending">移出列表</span>{{t.title}} <small>{{playlistDetail.retention==='append'?'歌单和音乐文件均保留':'音乐文件保留'}}</small></p></div><div v-else class="playlist-tracks"><div v-for="(t,i) in playlistDetail.tracks.slice(0,playlistVisible)" :key="t.asset_id||t.key"><span class="track-position">{{Number(i)+1}}</span><div><strong>{{t.title}}</strong><small>{{artists(t)}} · {{duration(t.duration)}}</small></div><button v-if="t.asset_id" class="text-button" :aria-label="'播放 '+t.title" @click="playSongs([t]);closeModal()"><Play :size="16"/>播放</button><button v-else class="text-button" @click="matchOriginal(t)">选版本</button></div><button v-if="playlistVisible<playlistDetail.tracks.length" class="secondary wide" @click="playlistVisible+=100">再显示 100 首</button></div></template>
      <template v-if="modal==='job' && jobDetail"><p class="eyebrow">{{stateNames[jobDetail.state]}} · {{date(jobDetail.created)}}</p><h2>{{jobDetail.title}}</h2><p :class="jobDetail.error?'inline-error':'muted'">{{jobDetail.error||jobDetail.stage}}</p><div v-if="jobDetail.result" class="result-box"><p v-if="jobDetail.result.reused">库内已有此版本，未重复下载。</p><p v-if="jobDetail.result.path">文件：{{jobDetail.result.path}}</p><p v-if="jobDetail.result.lyrics">{{jobDetail.result.lyrics.label}}</p><p v-if="jobDetail.result.scanned!==undefined">已扫描 {{jobDetail.result.scanned}} 个文件；{{jobDetail.result.errors.length}} 个需检查。</p><p v-if="jobDetail.result.added!==undefined">新增 {{jobDetail.result.added}} 首，移出列表 {{jobDetail.result.removed}} 首。</p></div><dl class="detail-grid"><dt>加入时间</dt><dd>{{taskDate(jobDetail.created)}}</dd><dt>首次开始</dt><dd>{{taskDate(jobDetail.started_at)}}</dd><dt>完成 / 结束</dt><dd>{{taskDate(jobDetail.finished_at)}}</dd><dt>累计执行耗时</dt><dd>{{elapsed(jobDetail.elapsed_seconds)}}</dd></dl><p class="fine">耗时不含排队、暂停和重试等待。{{jobDetail.timing_partial?'旧任务或异常中断的计时不完整，仅展示实际记录，未反推历史时间。':'重试会累计执行耗时，首次开始时间保持不变。'}}</p><h3>来源尝试记录</h3><p v-if="!jobDetail.attempts_log.length" class="muted">当前没有外部来源尝试记录。</p><ol class="attempt-log"><li v-for="a in jobDetail.attempts_log" :key="a.id"><strong>{{providerNames[a.source]||a.source}}</strong><small>{{date(a.created)}}</small><p>{{a.detail||a.status}}</p></li></ol><div class="button-row"><button v-if="['failed','paused','cancelled'].includes(jobDetail.state)" class="primary" @click="actionJob(jobDetail,'retry')">重试任务</button><button v-if="['queued','running'].includes(jobDetail.state)" class="secondary" @click="actionJob(jobDetail,'pause')">暂停</button><button v-if="['queued','running','paused'].includes(jobDetail.state)" class="secondary" @click="actionJob(jobDetail,'cancel')">取消</button></div></template>
      <template v-if="modal==='password'"><h2>更改访问密码</h2><form @submit.prevent="updatePassword"><label>当前密码<input v-model="oldPassword" type="password" autocomplete="current-password" required></label><label>新密码<input v-model="newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="256" required placeholder="至少 12 位"></label><p class="fine">修改后所有设备需要重新登录。</p><button class="primary wide" :disabled="!!busy">保存新密码</button></form></template>
      <template v-if="modal==='pwa-update'"><p class="eyebrow">更新当前设备的界面</p><h2>更新 PWA 缓存</h2><p>下载最新界面并刷新页面。登录、播放列表顺序和进度会保留，服务器下载任务继续运行。</p><p class="fine">刷新会暂停这台设备的播放，回来后点击播放继续。其他标签页可手动刷新以切换到新界面。</p><button class="primary wide" :disabled="!!busy||offline" @click="updatePwa">{{busy||'更新缓存并刷新'}}</button></template><template v-if="modal==='install'"><div class="install-heading"><img src="/icon.svg" width="64" height="64" alt="留声"><h2>把留声放在主屏幕</h2></div><p v-if="!secure">当前局域网 HTTP 地址可使用全部管理功能。通过可信 HTTPS 访问后，可启用 PWA 离线界面和安装能力。</p><p v-else>iPhone：在 Safari 的分享菜单中选择「添加到主屏幕」。Android：使用浏览器菜单中的「安装应用」。</p><p class="fine">断网时不会新增任务或显示虚假的成功状态。音乐播放需联网；锁屏后可尝试使用系统播放控制。</p><button class="secondary wide" @click="closeModal">知道了</button></template>
    </div>
  </dialog>
</template>
